  w.setPadding(0, 0, 0, 0);
  const shot = await webFace(W, H, info, medium, old);        // the card's own fonts
  FACE_ERROR = shot.error || null;
  if (shot.image) {
    // the picture comes back as a plain image of W*3 x H*3 pixels; drawn once into a context made at the widget's size and the screen's scale it becomes a picture of exactly
    // the right size and scale, one picture pixel per screen pixel (as it was before the fonts: handed over as it is, iOS stretched it and it was soft)
    const c2 = new DrawContext(); c2.size = new Size(W, H); c2.opaque = true; c2.respectScreenScale = true;
    c2.drawImageInRect(shot.image, new Rect(0, 0, W, H));
    w.backgroundImage = c2.getImage(); return w;
  }
  const ctx = new DrawContext(); ctx.size = new Size(W, H); ctx.opaque = true; ctx.respectScreenScale = true;
  drawFace(ctx, W, H, info, medium);
  if (FACE_ERROR) { ctx.setFont(Font.systemFont(14 * k)); ctx.setTextColor(col(WHITE, .45)); ctx.setTextAlignedLeft(); ctx.drawTextInRect('card fonts: ' + FACE_ERROR.slice(0, 80), new Rect(10 * k, H - 22 * k, W - 20 * k, 20 * k)); }      // says why the iPhone fonts are shown
  if (old) { ctx.setFont(Font.systemFont(18 * k)); ctx.setTextColor(col(WHITE, .6)); ctx.setTextAlignedRight(); ctx.drawTextInRect('old', new Rect(W - (medium ? 120 : 66) * k - 80 * k, 12 * k, 70 * k, 24 * k)); }
  w.backgroundImage = ctx.getImage();
