async function main() {
  const cfg = readConfig(); try { applyLook(readStore().look); } catch (e) { /* the card's colours */ }
  const family = (typeof config !== 'undefined' && config.widgetFamily) || 'small';
  const q = (typeof args !== 'undefined' && args.queryParameters) || {};
  if (!config.runsInWidget && q.open === 'big') {            // a tap on the widget: the big thermostat at once
    if (/^climate\./.test(String(q.entity || ''))) cfg.entity = String(q.entity);
    await presentBig(cfg); Script.complete(); return;
  }
  if (!config.runsInWidget) {
    const m = new Alert(); m.title = 'Okie thermostat widget'; m.message = cfg.token ? 'Set up again, or look at the widget.' : 'First time: set it up.';
    m.addAction('Set up'); m.addAction('Preview small'); m.addAction('Preview medium'); m.addAction('Open the big thermostat'); m.addCancelAction('Close');
    const pick = await m.presentSheet();
    if (pick === 3) { await presentBig(cfg); Script.complete(); return; }
    if (pick === 0) { if (await ask(cfg)) { const n = new Notification(); n.title = 'Saved'; n.body = 'Add a Scriptable widget and choose this script.'; await n.schedule(); } Script.complete(); return; }
    if (pick < 1) { Script.complete(); return; }
    const c2 = readConfig();
    if (!c2.token) { if (!(await ask(c2))) { Script.complete(); return; } }
    const got = await load(readConfig());
    const w = await makeWidget(got.info, pick === 1 ? 'small' : 'medium', readConfig(), got.old);
    if (FACE_ERROR) { const e = new Alert(); e.title = 'The card fonts could not be drawn'; e.message = FACE_ERROR + '\n\nThe widget uses the iPhone fonts until this works. Please send a screenshot of this message.'; e.addCancelAction('OK'); await e.presentAlert(); }
    else if (FACE_FONTS) { console.log('fonts: ' + FACE_FONTS); }
    if (pick === 1) await w.presentSmall(); else await w.presentMedium();
    Script.complete(); return;
  }
  if (!cfg.token) {
    const w = new ListWidget(); w.backgroundColor = new Color('#1b1411');
    const t = w.addText('Open Scriptable and run this script once to set it up'); t.textColor = Color.white(); t.font = Font.systemFont(13);
    Script.setWidget(w); Script.complete(); return;
  }
  const got = await load(cfg);
  Script.setWidget(await makeWidget(got.info, family, cfg, got.old));
  Script.complete();
}

